sys_script_include.script:
var MSS_Treasury_STSAPI_Utils = Class.create();
MSS_Treasury_STSAPI_Utils.prototype = {
    initialize: function() {
    },
	//to get number of task and Required banding groups from STS
    getNumOfTaskAndBandingGroup: function(region, currency, transactionAmount, instructionType, attempt, maxRetries) {
		var startTime = new Date().getTime(); // 开始时间
        // Initialize default values for attempt and maxRetries
        attempt = (typeof attempt !== 'undefined') ? attempt : 1;
        maxRetries = (typeof maxRetries !== 'undefined') ? maxRetries : 3;
        var resultObj = {};
        var isRquestError = false;
        var bandingGroup = '';
        var instType = '';
        // if (instructionType == 'Payment'){
        // 	instType = 'PAYMENT_SETTLEMENT';
        // }
        instructionType = 'PAYMENT_SETTLEMENT';
        region = 'HBAP';
		resultObj.approverPermission = 'Band 4';
		resultObj.numberOfApprovers = 2;
        try {
            var stsToken = gs.getProperty('x_hsb11_mss_tsd.eventOutbound_STS_token');
            var requestBody = 'region=' + region + '&currency=' + currency + '&amount=' + transactionAmount + '&instructionType=' + instructionType;
            var getNumAndBandGroupUri = gs.getProperty('x_hsb11_mss_tsd.hsbcmss_getNumAndBandGroup_STS_api');
            var r = new sn_ws.RESTMessageV2('HSBC STS API', 'Get The Details');
            r.setStringParameterNoEscape('getToken', stsToken);
            r.setStringParameterNoEscape('eventoutbound_base_sts_uri', getNumAndBandGroupUri);
            r.setStringParameterNoEscape('requestbody', requestBody);

            var response = r.execute();
            var responseBody = response.getBody();
            var resp_parsed = JSON.parse(responseBody);
            var httpStatus = resp_parsed.Status || resp_parsed.status;

            if (httpStatus != 'OK') {
                bandingGroup = resp_parsed.approverPermission;
                resultObj.approverPermission = this.getBand(bandingGroup);
                resultObj.numberOfApprovers = resp_parsed.numberOfApprovers;
                gs.info('Result Object: ' + JSON.stringify(resultObj));
				var endTime = new Date().getTime(); 
    gs.info('Execution time: ' + (endTime - startTime) + ' ms'); 
                return resultObj;
            } else {
                gs.error('Script Include - MSS_Treasury_Utils:- Unknown exception while call STS Checker Approval Limit API handling API');
            }
        } catch (e) {
            gs.error('Exception on attempt ' + attempt + ': ' + e.message);
            this.xMatterAlert("MINOR", 'Exception on attempt ' + attempt + ': ' + e.message);
        }

         if (attempt < maxRetries) {
             gs.info('Retrying API call (Attempt ' + (attempt + 1) + ' of ' + maxRetries + ')');
             return getNumOfTaskAndBandingGroup(region, currency, transactionAmount, instructionType, attempt + 1, maxRetries);
         }
        // gs.error('All retry attempts failed.');
		gs.info('Result Object: ' + JSON.stringify(resultObj));
		var endTime1 = new Date().getTime(); 
    gs.info('Execution time1: ' + (endTime1 - startTime) + ' ms');
        return resultObj;
    },
	getBand: function(role) {
        const roleToBandMap = {
            "FX_SETTLEMENT_CHECKER_1": "Band 7",
            "PAYMENT_CHECKER_1": "Band 7",
            "FX_SETTLEMENT_CHECKER_2": "Band 6",
            "PAYMENT_CHECKER_2": "Band 6",
            "FX_SETTLEMENT_CHECKER_3": "Band 5",
            "PAYMENT_CHECKER_3": "Band 5",
            "FX_SETTLEMENT_CHECKER_4": "Band 4",
            "PAYMENT_CHECKER_4": "Band 4"
        };

        return roleToBandMap[role] || "Unknown Band";
    },

    type: 'MSS_Treasury_STSAPI_Utils'
};
